from django.shortcuts import render, get_object_or_404, redirect
from django.contrib.auth import get_user_model
from django.db.models import Q
from django.contrib import messages

from apps.authentication.decorators import requiere_permiso
from .services import (
    actualizar_usuario_en_keycloak,
    obtener_roles_disponibles,
    obtener_roles_de_usuario,
    actualizar_roles_de_usuario,
    sincronizar_usuarios_desde_keycloak,
)

User = get_user_model()


@requiere_permiso('usuarios')
def lista_usuarios_view(request):
    query = request.GET.get('q', '').strip()
    try:
        roles_por_usuario = sincronizar_usuarios_desde_keycloak()
    except Exception:
        roles_por_usuario = {}
        messages.warning(
            request,
            'No fue posible actualizar los usuarios desde Keycloak. '
            'Se muestran los datos locales disponibles.',
        )

    usuarios = User.objects.filter(is_active=True).order_by('id')

    if query:
        usuarios = usuarios.filter(
            Q(first_name__icontains=query) |
            Q(last_name__icontains=query) |
            Q(email__icontains=query)
        )

    return render(request, 'user_list.html', {
        'usuarios': usuarios,
        'query': query,
        'roles_por_usuario': roles_por_usuario,
    })


@requiere_permiso('usuarios')
def editar_usuario_view(request, user_id):
    usuario = get_object_or_404(User, id=user_id)

    if request.method == 'POST':
        first_name = request.POST.get('first_name', '').strip()
        last_name = request.POST.get('last_name', '').strip()

        raw_is_active = request.POST.get('is_active')
        is_active = raw_is_active in ['on', 'true', 'True', True]

        try:
            actualizar_usuario_en_keycloak(
                email=usuario.email,
                first_name=first_name,
                last_name=last_name,
                is_active=is_active
            )

            usuario.first_name = first_name
            usuario.last_name = last_name
            usuario.is_active = is_active
            usuario.save()

            messages.success(request, f"Usuario {usuario.email} actualizado correctamente.")
            return redirect('lista_usuarios')

        except Exception as e:
            messages.error(request, f"Error al actualizar en Keycloak: {str(e)}")

    return render(request, 'user_edit.html', {'usuario': usuario})


@requiere_permiso('gestion_roles')
def editar_roles_view(request, user_id):
    """
    Permite a un admin (rol 'admin' o 'gestion_roles' en Keycloak) asignar
    o quitar realm roles de otro usuario. Todo se lee/escribe directo
    contra la Admin API de Keycloak — Django no persiste el rol en
    ningún lado propio.
    """
    usuario = get_object_or_404(User, id=user_id)

    try:
        roles_disponibles = obtener_roles_disponibles()
        roles_actuales = obtener_roles_de_usuario(usuario.email)
    except Exception as e:
        messages.error(request, f"Error al consultar roles en Keycloak: {str(e)}")
        return redirect('lista_usuarios')

    if request.method == 'POST':
        roles_seleccionados = request.POST.getlist('roles')
        try:
            actualizar_roles_de_usuario(usuario.email, roles_seleccionados)
            messages.success(
                request,
                f"Roles de {usuario.email} actualizados. "
                f"Debe volver a loguearse para que el cambio aplique."
            )
            return redirect('lista_usuarios')
        except Exception as e:
            messages.error(request, f"Error al actualizar roles en Keycloak: {str(e)}")

    return render(request, 'user_roles.html', {
        'usuario': usuario,
        'roles_disponibles': roles_disponibles,
        'roles_actuales': roles_actuales,
    })

"""
Módulo de formularios para la aplicación de Clientes.
"""

from django import forms
from django.contrib.auth import get_user_model
from apps.clientes.models import Cliente

User = get_user_model()


class ClienteForm(forms.ModelForm):

    class Meta:
        model = Cliente
        fields = [
            'tipo_cliente',
            'identificador',
            'nombre',
            'apellido',
            'razon_social',
            'segmento',
        ]

    def clean_segmento(self):
        segmento = self.cleaned_data.get('segmento')
        return {'ESTANDAR': 'MINORISTA', 'PREMIUM': 'VIP'}.get(segmento, segmento)

    def clean_identificador(self):
        """Valida únicamente que el identificador/documento no esté registrado

        en otro perfil de cliente. Ya no exige que el usuario exista previamente.
        """
        identificador = self.cleaned_data.get('identificador')

        if not identificador:
            return identificador

        # 1. Validar unicidad del identificador dentro de la tabla Cliente
        cliente_existente = Cliente.objects.filter(identificador=identificador)
        if self.instance and self.instance.pk:
            cliente_existente = cliente_existente.exclude(
                pk=self.instance.pk
            )

        if cliente_existente.exists():
            raise forms.ValidationError(
                'Ya existe un perfil de cliente registrado con este documento/identificador.'
            )

        return identificador

    def clean(self):
        """Validaciones condicionales según el tipo de cliente."""
        cleaned_data = super().clean()
        tipo_cliente = cleaned_data.get('tipo_cliente')
        nombre = cleaned_data.get('nombre')
        apellido = cleaned_data.get('apellido')
        razon_social = cleaned_data.get('razon_social')

        if tipo_cliente == Cliente.TIPO_FISICA:
            if not nombre:
                self.add_error(
                    'nombre', 'El nombre es obligatorio para personas físicas.'
                )
            if not apellido:
                self.add_error(
                    'apellido',
                    'El apellido es obligatorio para personas físicas.',
                )

        elif tipo_cliente == Cliente.TIPO_JURIDICA:
            if not razon_social:
                self.add_error(
                    'razon_social',
                    'La razón social es obligatoria para personas jurídicas.',
                )

        return cleaned_data

    def save(self, commit=True):
        """Asigna automáticamente el usuario si ya existe con ese identificador.

        Si no existe, se crea el cliente normalmente sin forzar la vinculación.
        """
        cliente = super().save(commit=False)
        identificador = self.cleaned_data.get('identificador')

        if identificador:
            usuario = User.objects.filter(username=identificador).first()
            if usuario:
                cliente.user = usuario

        if commit:
            cliente.save()
            self.save_m2m()

        return cliente


class AsociarUsuarioClienteForm(forms.Form):
    """Formulario independiente para asociar o desasociar Usuarios a un Cliente."""

    class UsuarioModelMultipleChoiceField(forms.ModelMultipleChoiceField):
        def label_from_instance(self, obj):
            nombre_completo = f"{obj.first_name} {obj.last_name}".strip()
            return nombre_completo if nombre_completo else obj.username

    usuarios = UsuarioModelMultipleChoiceField(
        queryset=None,
        widget=forms.CheckboxSelectMultiple,
        required=False,
        label="Usuarios del Sistema",
    )

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.fields['usuarios'].queryset = User.objects.filter(
            is_active=True
        ).order_by('first_name', 'last_name')

